  stroke: #FFFFFF;
  stroke-width: 2.8;
  transition: opacity 180ms ease,
        r 160ms ease;
}
.gauge-history-point.hovered {
  r: 9.5px;
  opacity: 1;
}
.gauge-history-hover-line {
  stroke: #001B8E;
  stroke-width: 2.2;
  stroke-dasharray: 7 6;
  opacity: 0.68;
  pointer-events: none;
}
.gauge-history-hover-hitbox {
  fill: transparent;
  cursor: crosshair;
  pointer-events: all;
}
.gauge-history-legend {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
  margin: 0;
}
.gauge-history-legend-item {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 10px;
  border: 1px solid #DBE4F0;
  border-radius: 999px;
  background: #FFFFFF;
  color: #334155;
  font-size: 10px;
  font-weight: 800;
  cursor: pointer;
  transition: transform 150ms ease, box-shadow 150ms ease, opacity 150ms ease;
}
.gauge-history-legend-item::before {
  content: "";
  width: 9px;
  height: 9px;
  border-radius: 999px;
  background: var(--series-color);
}
.gauge-history-legend-item:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 10px rgba(15, 23, 42, 0.08);
}
.gauge-history-legend-item--inactive {
  opacity: 0.42;
}
.gauge-history-side-panel {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 14px;
  align-self: stretch;
  min-height: 0;
  padding: 16px 16px;
  border: 1px solid #DBE4F0;
  border-radius: 12px;
  background: #EEF4FF;
}
.gauge-history-info-card,
.gauge-history-update-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0;
  border: 0;
  border-radius: 0;
}
.gauge-history-info-card {
  align-items: flex-start;
  background: transparent;
}
.gauge-history-update-card {
  background: transparent;
  white-space: nowrap;
}
.gauge-history-update-card--compact {
  justify-self: end;
  align-self: end;
  padding: 0 4px 0 0;
}
.gauge-history-info-card > span,
.gauge-history-update-card > span {
  flex: 0 0 auto;
  width: 26px;
  height: 26px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #FFFFFF;
  color: #001B8E;
  font-size: 14px;
  font-weight: 900;
}
.gauge-history-info-card p {
  margin: 0;
