  display: grid;
  gap: 16px;
  align-content: start;
  min-height: 0;
}
.gauge-history-definition-item {
  display: grid;
  grid-template-columns: 58px minmax(0, 1fr);
  gap: 12px;
  align-items: start;
}
.gauge-history-definition-item::before {
  content: "";
  grid-column: 1;
  width: 36px;
  height: 5px;
  margin-top: 10px;
  border-radius: 999px;
  background: var(--series-color);
}
.gauge-history-definition-item strong {
  grid-column: 1;
  grid-row: 1;
  margin-left: 45px;
  color: var(--series-color);
  font-size: 15px;
  font-weight: 900;
}
.gauge-history-definition-item p {
  grid-column: 2;
  grid-row: 1;
  margin: 0;
  color: #0F2A6B;
  font-size: 13px;
  font-weight: 650;
  line-height: 1.28;
}
.gauge-history-tooltip {
  position: absolute;
  z-index: 2;
  min-width: 390px;
  display: grid;
  gap: 10px;
  padding: 18px 20px;
  border: 1px solid rgba(203, 213, 225, 0.95);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.98);
  color: #0F172A;
  box-shadow: 0 18px 42px rgba(15, 23, 42, 0.22), 0 3px 10px rgba(15, 23, 42, 0.08);
  font-size: 21px;
  font-weight: 750;
  line-height: 1.18;
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, calc(-100% - 12px));
  transition: opacity 120ms ease;
}
.gauge-history-tooltip.visible {
  opacity: 1;
}
.gauge-history-tooltip .title {
  margin-bottom: 4px;
  padding-bottom: 9px;
  border-bottom: 1px solid #E2E8F0;
  color: #001B8E;
  font-size: 24px;
  font-weight: 900;
}
.gauge-history-tooltip .metric-row {
  display: grid;
  grid-template-columns: 70px minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  min-height: 42px;
}
.gauge-history-tooltip .metric-name {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: #334155;
  font-size: 20px;
  font-weight: 900;
}
.gauge-history-tooltip .metric-name::before {
  content: "";
  width: 13px;
  height: 13px;
  border-radius: 999px;
  background: var(--series-color);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--series-color) 16%, transparent);
}
.gauge-history-tooltip .metric-value {
  color: #0F172A;
  font-size: 24px;
  font-weight: 950;
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.gauge-history-tooltip .metric-delta {
  min-width: 100px;
  padding: 7px 11px;
  border-radius: 999px;
  font-size: 20px;
  font-weight: 950;
  text-align: center;
  font-variant-numeric: tabular-nums;
}
.gauge-history-tooltip .metric-delta.positive {
  background: #DCFCE7;
  color: #15803D;
}
.gauge-history-tooltip .metric-delta.negative {
  background: #FEE2E2;
  color: #B91C1C;
}
.gauge-history-tooltip .metric-delta.neutral {
  background: #E2E8F0;
  color: #475569;
}
@keyframes gauge-modal-overlay-enter {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes gauge-modal-enter {
  from {
    opacity: 0;
    transform: translateY(18px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}
